            {f > 0 && <line x1={a.x} y1={a.y + 10} x2={x2} y2={y2} stroke={COLOR[e.arm]} strokeWidth={2.5} />}
            {f >= 1 && <polygon points={`${b.x},${b.y - 10} ${b.x - 4},${b.y - 17} ${b.x + 4},${b.y - 17}`} fill={COLOR[e.arm]} />}
          </g>
