      {/* drug overlays */}
      {drugs && (
        <g fontSize={10} fontWeight={600}>
          {/* warfarin: II, VII, IX, X */}
          {["II", "VII", "IX", "X"].map((id) => {
            const n = byId(id);
            return <circle key={id} cx={n.x - n.label.length * 2.8 - 14} cy={n.y} r={6} fill="#7c3aed" opacity={0.9} />;
